private Layout computeLayout() {
    float usableW = Math.max(1.0f, getWidth());
    float usableH = Math.max(1.0f, getHeight());
    int scale = Math.max(1, Math.min(4, (int) Math.floor(usableH / MainActivity.HUD_SECTION_LEFT)));
    while (scale > 1 && ((int) Math.floor(usableW / scale)) < MainActivity.GENESIS_CANVAS_W) {

    while (scale > 1 && ((int) Math.floor(usableW / scale)) < MainActivity.GENESIS_CANVAS_W) {
        scale--;
    }
    int viewportLogicalWidth = Math.max(240, (int) Math.floor(usableW / scale));
    int viewportLogicalHeight = Math.max(240, (int) Math.floor(usableH / scale));
    float viewportWidth = viewportLogicalWidth * scale;
    float viewportHeight = viewportLogicalHeight * scale;
    float hudScale = ClassicHudScale762.resolve(MainActivity.this.hudScalePreset, scale, viewportWidth, viewportHeight, 108.0f, MainActivity.HUD_SECTION_MENU_BOTTOM);
    float hudWidth = 108.0f * hudScale;
    float hudLeft = Math.max(0.0f, (0.0f + viewportWidth) - hudWidth);
    return new Layout(scale, 0.0f, 0.0f, viewportLogicalWidth, viewportLogicalHeight, viewportWidth, viewportHeight, hudLeft, hudWidth, viewportHeight, hudScale, viewportWidth, viewportHeight);
}

