                    float targetX3 = targetX2;
                    int x = packed & 63;
                    int j = y;
                    int j2 = (packed >>> 6) & 63;
                    if (x >= minX) {
                        targetY3 = targetY4;
                        if (x < minX + mapW && j2 >= minY && j2 < minY + mapH) {
                            sx2 += ((x - minX) + f) * MainActivity.TACTICAL_CURSOR_SPEED_CELLS_PER_SECOND;
                            sy += ((j2 - minY) + f) * MainActivity.TACTICAL_CURSOR_SPEED_CELLS_PER_SECOND;
                            used++;
                        }
                    } else {
                        targetY3 = targetY4;
                    }
                    y = j + 1;
                    targetX2 = targetX3;
                    targetY4 = targetY3;
                }
                targetX = targetX2;
                targetY2 = targetY4;
                if (used > 0) {
                    targetX2 = sx2 / used;
                    float targetY5 = sy / used;
                    found = true;
                    targetY4 = targetY5;
                    i3++;
                    f2 = f;
                }
            }
        }
        targetX2 = targetX;
        targetY4 = targetY2;
        i3++;
        f2 = f;
    }
    float targetX4 = targetX2;
    float f3 = f2;
    float targetY6 = targetY4;
    if (!found) {
        float sx3 = 0.0f;
        float sy2 = 0.0f;
        int used2 = 0;
        int i4 = 0;
        for (i2 = 128; i4 < i2; i2 = 128) {
            int base2 = (i4 * 4) + MainActivity.UNIT_OFFSET;
            int meta2 = MainActivity.this.renderWords[base2];
            if ((meta2 & i) != 0 && (meta2 & 255) == playerHouse) {
                long pos = MainActivity.this.renderWords[base2 + 1] & 4294967295L;
                float wx = (pos & 65535) / 256.0f;
                float wy = ((pos >>> 16) & 65535) / 256.0f;
                sx3 += (wx - minX) * MainActivity.TACTICAL_CURSOR_SPEED_CELLS_PER_SECOND;
                sy2 += (wy - minY) * MainActivity.TACTICAL_CURSOR_SPEED_CELLS_PER_SECOND;
                used2++;
            }
            i4++;
