        }
        if (used2 > 0) {
            float targetX5 = sx3 / used2;
            sx = targetX5;
            targetY = sy2 / used2;
            this.cameraX = sx - (this.currentActiveViewportLogicalW * f3);
            this.cameraY = targetY - (this.currentViewportLogicalH * f3);
            this.cameraInitialized = SMOOTH_HUD_PURCHASE_SCROLL;
        }
    }
    sx = targetX4;
    targetY = targetY6;
    this.cameraX = sx - (this.currentActiveViewportLogicalW * f3);
    this.cameraY = targetY - (this.currentViewportLogicalH * f3);
    this.cameraInitialized = SMOOTH_HUD_PURCHASE_SCROLL;
}

private void clampCamera() {
    float maxX = Math.max(0.0f, (this.currentMapW * 32) - this.currentActiveViewportLogicalW);
    float maxY = Math.max(0.0f, (this.currentMapH * 32) - this.currentViewportLogicalH);
